select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_TARE_PARTICIPANT','RRL_STOCK_TARE_RESOLVE','RRL_STOCK_TARE_CMD','RRL_STOCK_POSTING_API','RRL_TARE_STORE_DEBT','RRL_TARE_RESOLUTION_GUARD','RRL_TARE_BALANCE_GUARD') order by OBJECT_NAME,OBJECT_TYPE;
select MIGRATION_ID,STATUS from RRL_SCHEMA_MIGRATIONS where MIGRATION_ID='2026-10-10-100-tare-damage-writeoff';
select count(*) INVALID_DEBT from RRL_TARE_STORE_DEBT where OUTSTANDING_QTY<0 or LOAN_QTY<0;
